package httpapi

// The route table (audit G3). Every authenticated route of the API is one row in routes: its method and
// pattern (Go's http.ServeMux syntax, {name} for a path segment), what a member who has not finished onboarding
// or who is in the deletion grace period may reach, the per-account limiter taken before the handler, and the
// handler. The table is the only description of the API's routes: the ServeMux is built from it, the onboarding
// and deletion exemptions are read from it, and TestRoutesMatchOpenAPI walks it against
// docs/api/openapi-foundation.json (generated by scripts/build_foundation_contract.py), so a route that is
// added, renamed or dropped on one side only fails the build.
//
// Handler order for a member request (Handler in server.go, then serveRoute below):
//
//	origin and CORS, probes, address rate limit, minimum client version (426), development login,
//	bearer token (401), then the route: no row -> 404; deletion grace period (401); onboarding (403
//	ONBOARDING_REQUIRED); malformed {...Id} segment (404); the row's limiter (429); the handler.
//
// Chat routes keep their own dispatcher (chat.go, chatmedia.go): their rows point at serveChat, which asks
// chatRoute to serve the request. A route added there must be added here too, or it is unreachable.

import (
	"context"
	"net/http"
	"net/url"
	"path"
	"strings"

	"hiyall/services/api/internal/store"
)

type access uint8

const (
	// preOnboarding marks a route an account may reach before it has completed onboarding.
	preOnboarding access = 1 << iota
	// whilePendingDeletion marks a route a member in the 30 day deletion grace period may reach; every other
	// route answers them as it does any inactive account (401 UNAUTHENTICATED).
	whilePendingDeletion
)

// stage says where a request is served when it is not an ordinary member route.
type stage uint8

const (
	stageMember   stage = iota
	stagePublic         // probes, answered before rate limiting and authentication (health in ops.go)
	stageDev            // POST /dev/session, only with development authentication
	stageRealtime       // the WebSocket, outside the request deadline (realtimeGateway)
)

// limitSpec is the per-account budget a route takes before its handler runs: the limiter, the Retry-After
// header and the message of the 429 RATE_LIMITED.
type limitSpec struct {
	limiter    func(*API) *keyedLimiter
	retryAfter string
	message    string
}

const slowDown = "Slow down a little and try again"

var (
	limitMediaComplete = &limitSpec{func(a *API) *keyedLimiter { return a.mediaComplete }, "2", slowDown}
	limitSearch        = &limitSpec{func(a *API) *keyedLimiter { return a.search }, "2", "Try again shortly"}
	limitProfileEdits  = &limitSpec{func(a *API) *keyedLimiter { return a.profileEdits }, "3", slowDown}
	limitGraph         = &limitSpec{func(a *API) *keyedLimiter { return a.graph }, "2", slowDown}
	limitVisitors      = &limitSpec{func(a *API) *keyedLimiter { return a.lists }, "1", slowDown}
	limitContent       = &limitSpec{func(a *API) *keyedLimiter { return a.content }, "5", slowDown}
	limitLists         = &limitSpec{func(a *API) *keyedLimiter { return a.lists }, "5", slowDown}
	limitUploads       = &limitSpec{func(a *API) *keyedLimiter { return a.uploads }, "5", slowDown}
	limitSpaces        = &limitSpec{func(a *API) *keyedLimiter { return a.content }, "1", "Slow down and try again"}
)

type handlerFunc = func(a *API, w http.ResponseWriter, r *http.Request, p store.Principal)

type route struct {
	// Method is the one HTTP method served. Empty serves every method (used for the 405 answers).
	Method  string
	Pattern string
	Access  access
	// Limit is taken before the handler and after the {...Id} check. nil: the handler limits itself or the
	// route is not limited.
	Limit *limitSpec
	// BadID is the message of the 404 for a malformed first {...Id} segment; empty is "Endpoint unavailable".
	BadID string
	Stage stage
	// Handler is nil for the rows served before authentication (Stage is not stageMember).
	Handler handlerFunc
}

