// patternOf is how a row is registered with the ServeMux: "METHOD /path", or "/path" for every method.
func (rt *route) patternOf() string {
	if rt.Method == "" {
		return rt.Pattern
	}
	return rt.Method + " " + rt.Pattern
}

// idWildcards are the {name} segments of a pattern that must be ids: those ending in Id.
func (rt *route) idWildcards() []string {
	var names []string
	for _, seg := range strings.Split(rt.Pattern, "/") {
		if len(seg) > 2 && seg[0] == '{' && strings.HasSuffix(seg, "Id}") {
			names = append(names, seg[1:len(seg)-1])
		}
	}
	return names
}

type router struct {
	mux   *http.ServeMux
	byKey map[string]*route
}

// apiRouter serves every member route. It is built once: the rows hold method expressions, not instances.
var apiRouter *router

func init() { apiRouter = newRouter(routes) }

func newRouter(table []route) *router {
	rt := &router{mux: http.NewServeMux(), byKey: map[string]*route{}}
	for i := range table {
		row := &table[i]
		if row.Handler == nil {
			continue
		}
		rt.byKey[row.patternOf()] = row
		rt.mux.HandleFunc(row.patternOf(), func(w http.ResponseWriter, r *http.Request) { serveRoute(row, w, r) })
	}
	// Every request no row matches, or that a GET row would match as HEAD: 404 after the same gates.
	rt.mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) { serveUnmatched(w, r) })
	return rt
}

// lookup is the row that serves a method and path, nil when none does.
func (rt *router) lookup(method, path string) *route {
	_, pattern := rt.mux.Handler(&http.Request{Method: method, URL: &url.URL{Path: path}})
	row := rt.byKey[pattern]
	if row != nil && row.Method != "" && row.Method != method {
		return nil
	}
	return row
}

// onboardingExempt is whether an account that has not finished onboarding may reach the route: its own
// profile and privacy (to choose a name and username), the onboarding endpoints, the username check, deletion
// and session management. Everything else, including /v1/realtime, waits until onboarding is complete.
func onboardingExempt(method, path string) bool {
	if row := apiRouter.lookup(method, path); row != nil {
		return row.Access&preOnboarding != 0
	}
	return unmatchedExempt(method, path, preOnboarding)
}

// pendingDeletionAllowed is everything a member in the 30 day grace period may reach: the deletion status,
// the cancel and the sign-out routes. Every other route answers as it does for any inactive account
// (401 UNAUTHENTICATED), so such a member vanishes from the app's point of view but can still change their mind.
func pendingDeletionAllowed(method, path string) bool {
	if row := apiRouter.lookup(method, path); row != nil {
		return row.Access&whilePendingDeletion != 0
	}
	return unmatchedExempt(method, path, whilePendingDeletion)
}

// unmatchedExempt keeps the gates as they were for requests that match no row: a path the account would be
// allowed to ask for with another method still gets its 404 and not a gate refusal. It is not a way to a
// handler: nothing is served for such a request.
func unmatchedExempt(method, path string, kind access) bool {
	switch kind {
	case preOnboarding:
		return strings.HasPrefix(path, "/v1/auth/") || path == "/v1/me/deletion"
	case whilePendingDeletion:
		return method == http.MethodDelete && strings.HasPrefix(path, "/v1/auth/sessions/")
	}
	return false
}

type dispatchKey struct{}

// dispatch is what the ServeMux handlers need and cannot be passed: the API and the signed-in principal.
type dispatch struct {
	a *API
	p store.Principal
}

// route serves an authenticated request: the ServeMux picks the row, serveRoute applies it.
func (a *API) route(w http.ResponseWriter, r *http.Request, p store.Principal) {
	ctx := context.WithValue(r.Context(), dispatchKey{}, &dispatch{a, p})
	r = r.WithContext(ctx)
	if cleaned(r.URL.Path) != r.URL.Path {
		// The ServeMux would redirect an unclean path (//, ., ..); the API never redirects.
		serveUnmatched(w, r)
		return
	}
	apiRouter.mux.ServeHTTP(w, r)
}

func cleaned(p string) string {
	if p == "" {
		return "/"
	}
	np := path.Clean(p)
	if p[len(p)-1] == '/' && np != "/" {
		np += "/"
	}
	return np
}

func serveRoute(row *route, w http.ResponseWriter, r *http.Request) {
	d := r.Context().Value(dispatchKey{}).(*dispatch)
	a, p := d.a, d.p
	if row.Method != "" && r.Method != row.Method {
		// A GET row also matches HEAD in the ServeMux; the API serves GET only. A path with a 405 row answers
		// every other method with it.
		if any := apiRouter.byKey[row.Pattern]; any != nil {
			serveRoute(any, w, r)
			return
		}
		serveUnmatched(w, r)
		return
	}
	if !a.gate(w, r, p, row.Access) {
		return
	}
	for i, name := range row.idWildcards() {
		if !isID(r.PathValue(name)) {
			message := "Endpoint unavailable"
			if i == 0 && row.BadID != "" {
				message = row.BadID
			}
			a.failure(w, r, 404, "NOT_FOUND", message)
			return
		}
	}
	if row.Limit != nil && !a.admit(w, r, p, row.Limit) {
		return
	}
	row.Handler(a, w, r, p)
}

// serveUnmatched answers a request no row serves. It passes the same gates, with the exemptions a path of this
// kind had before the table (unmatchedExempt), so a member who has not onboarded still gets 403 and not a
// 404 that tells which paths exist.
func serveUnmatched(w http.ResponseWriter, r *http.Request) {
	d := r.Context().Value(dispatchKey{}).(*dispatch)
	a, p := d.a, d.p
	var acc access
	if unmatchedExempt(r.Method, r.URL.Path, preOnboarding) {
		acc |= preOnboarding
	}
	if unmatchedExempt(r.Method, r.URL.Path, whilePendingDeletion) {
		acc |= whilePendingDeletion
	}
	if !a.gate(w, r, p, acc) {
		return
	}
	message := "Endpoint unavailable"
	if parts := strings.Split(strings.Trim(r.URL.Path, "/"), "/"); len(parts) >= 3 && parts[0] == "v1" {
		// What these families answered for an id that is not an id, whatever the rest of the request was.
		switch {
		case len(parts) == 4 && parts[1] == "users" && !isID(parts[2]):
			message = badMember
		case parts[1] == "spaces" && !isID(parts[2]):
			message = badSpace
		}
	}
	a.failure(w, r, 404, "NOT_FOUND", message)
}

// gate applies the deletion grace period and onboarding to a route with access acc, and answers when refused.
func (a *API) gate(w http.ResponseWriter, r *http.Request, p store.Principal, acc access) bool {
	if p.PendingDeletion && acc&whilePendingDeletion == 0 {
		a.failure(w, r, 401, "UNAUTHENTICATED", "Sign in to continue")
		return false
	}
	if !p.Onboarded && acc&preOnboarding == 0 {
		a.failOnboarding(w, r)
		return false
	}
	return true
}

// admit takes a token from the route's limiter for the member, and answers 429 when there is none.
func (a *API) admit(w http.ResponseWriter, r *http.Request, p store.Principal, l *limitSpec) bool {
	if l.limiter(a).allow(p.UserID) {
		return true
	}
	w.Header().Set("Retry-After", l.retryAfter)
	a.failure(w, r, 429, "RATE_LIMITED", l.message)
	return false
}

func (a *API) methodNotAllowed(w http.ResponseWriter, r *http.Request, _ store.Principal) {
	a.failure(w, r, 405, "METHOD_NOT_ALLOWED", "Method unavailable")
}

// serveChat hands a chat route to the chat dispatcher, which matches its own method and ids.
func (a *API) serveChat(w http.ResponseWriter, r *http.Request, p store.Principal) {
	parts := strings.Split(strings.Trim(r.URL.Path, "/"), "/")
	if !a.chatRoute(w, r, p, parts) {
		a.failure(w, r, 404, "NOT_FOUND", "Endpoint unavailable")
	}
}
